export function getSchools(branch) {
  return branch === "shia" ? SCHOOLS_SHIA : SCHOOLS_SUNNI;
}

export function getBeliefs(branch) {
  if (branch === "shia") return [...BELIEFS_SHIA, ...BELIEFS_SHIA_FURU];
  return [...BELIEFS_SUNNI, ...BELIEFS_SUNNI_AQEEDAH];
}

export function getScholars(branch) {
  if (branch === "shia") return [...SCHOLARS_SHIA_CLASSICAL, ...SCHOLARS_SHIA_LIVING];
  return [...SCHOLARS_SUNNI_CLASSICAL, ...SCHOLARS_SUNNI_LIVING];
}

export function getScholarById(id, branch) {
  return getScholars(branch).find(s => s.id === id) || null;
}

